def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform, nonzero separator between the two panels.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            return [
                [2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(w)]
                for i in range(min(len(top), len(bottom)))
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left_width = c
            right_width = w - c - 1
            width = min(left_width, right_width)
            return [
                [2 if grid[r][j] != 0 and grid[r][c + 1 + j] != 0 else 0
                 for j in range(width)]
                for r in range(h)
            ]

    return grid
